        success: (h2) => { h2.res('iran', { military: 6, stability: -2 }); h2.rel('iran', 'russia', 6); h2.rel('iran', 'china', 6); h2.W('warIntensity', -6); h2.res('us', { political: -1 }); },
        fail: (h2) => { h2.res('iran', { stability: -5 }); },
