        success: (h2) => { h2.W('iranSanctions', -9); h2.W('hormuz', 15); h2.W('warIntensity', -10); h2.inf('hormuz', 'iran', -5); h2.res('iran', { money: 5, political: 2 }); h2.rel('iran', 'us', 6); h2.set('memorandum2', true); },
